package com.eilo.foundation
import org.junit.Assert.*
import org.junit.Test
class GenericFollowupTest {
    private class Sink:NativeClauseSink {val texts=mutableListOf<String>();val callbacks=mutableListOf<(OfflineSpeechEvent)->Unit>();override fun enqueue(token:GenerationToken,text:String,event:(OfflineSpeechEvent)->Unit):Boolean{texts+=text;callbacks+=event;return true};override fun cancel(){}}
    private fun setup(time:FakeTime)=testController(clock=time,scheduler=time).also{assertTrue(it.dispatch(ControllerEvent.START));assertNull(it.beginGenericFollowup(it.token()!!));assertTrue(it.dispatch(ControllerEvent.SPEECH_DETECTED,token=it.token()))}
    private fun turn(c:NativeController,s:Sink,answer:String,check:(GenericReplyRequest)->Unit={})=GenericSpokenTurn(c,c.token()!!,s,true,GenericReplyStarter{_,request,r,f->check(request);val bytes=answer.toByteArray();r(bytes,bytes.size);f(LlmJobResult.COMPLETED);true})
    @Test fun twoTurnsRetainOnlyCompletedContext(){val time=FakeTime();val c=setup(time);val s=Sink();val first=turn(c,s,"Blue.");assertTrue(first.submit(AsrText("Name one colour.",true),1f));assertTrue(c.genericContext(c.token()!!)!!.isEmpty());s.callbacks[0](OfflineSpeechEvent.STARTED);s.callbacks[0](OfflineSpeechEvent.FINISHED);val post=c.token()!!;assertNull(c.beginGenericFollowup(post));time.now=300;val next=c.beginGenericFollowup(post)!!;assertEquals(post.sessionId,next.sessionId);assertTrue(post.cancelled);val second=turn(c,s,"Yes, blue."){assertEquals(2,it.history.size);assertEquals("Blue.",it.history[1].text)};assertTrue(second.submit(AsrText("Can you repeat that?",true),1f));s.callbacks[1](OfflineSpeechEvent.STARTED);s.callbacks[1](OfflineSpeechEvent.FINISHED);assertEquals(ControllerState.STANDBY,c.state())}
    @Test fun idleEndStopPrivacyClear(){for(mode in 0..3){val time=FakeTime();val c=setup(time);val s=Sink();val first=turn(c,s,"Blue.");assertTrue(first.submit(AsrText("Name one colour.",true),1f));s.callbacks[0](OfflineSpeechEvent.STARTED);s.callbacks[0](OfflineSpeechEvent.FINISHED);val old=c.token()!!;when(mode){0->{time.now=60000;time.jobs.last().task()};1->assertTrue(c.endConversation());2->{c.stop();assertTrue(c.dispatch(ControllerEvent.START))};else->{c.privacyTransition(PrivacyChange.PRIVATE_SESSION);assertTrue(c.dispatch(ControllerEvent.START))}};assertNull(c.beginGenericFollowup(old));time.now+=300;assertTrue(c.dispatch(ControllerEvent.SPEECH_DETECTED,token=c.token()));assertTrue(c.genericContext(c.token()!!)!!.isEmpty())}}
    @Test fun boundedPairs(){val c=setup(FakeTime());assertTrue(c.dispatch(ControllerEvent.ENDPOINT,token=c.token()));repeat(12){c.recordGenericTurn(c.token()!!,"Question $it","b".repeat(1000))};val h=c.genericContext(c.token()!!)!!;assertEquals(8,h.size);assertEquals("Question 8",h.first().text);assertTrue(h.sumOf{it.text.toByteArray().size}<=8192)}    @Test fun combinedSuffixFeedsAsrThenOneReply(){val time=FakeTime();val c=testController(clock=time,scheduler=time);assertTrue(c.dispatch(ControllerEvent.START));val h=WakeQuestionHandoff();assertTrue(h.offer(ShortArray(640){100},640,0));assertTrue(c.dispatch(ControllerEvent.SPEECH_DETECTED,token=c.token()));val token=c.token()!!;var samples=0;val backend=object:AsrStream{override fun accept(pcm:FloatArray,count:Int){samples+=count};override fun text(finish:Boolean)="Name one colour.";override fun close(){}};val asr=StreamingAsr(token,{c.recognitionAllowed(token)},{backend});assertTrue(h.activate(token,320,{c.recognitionAllowed(token)},{p,n->assertTrue(asr.accept(p,n))}));assertTrue(h.offer(ShortArray(640){100},640,320));assertEquals(640,samples);val s=Sink();val joined=turn(c,s,"Blue.");assertTrue(joined.submit(asr.poll(true)!!,1f));assertEquals(listOf("Blue."),s.texts);h.close()}

}
